INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2018-spring-am-41','exam-sg','事業継続計画・BCP','standard','single_choice','【平成30年度 春期 午前 問41】事業継続計画（BCP）について監査を実施した結果，適切な状況と判断されるものはどれか。','[{"id":"a","text":"従業員の緊急連絡先リストを作成し，最新版に更新している。"},{"id":"b","text":"重要書類は複製せずに1か所で集中保管している。"},{"id":"c","text":"全ての業務について，優先順位なしに同一水準のBCPを策定している。"},{"id":"d","text":"平時にはBCPを従業員に非公開としている。"}]','"a"','緊急連絡先リストを最新に保つことは，緊急時の連絡体制を確保するための適切なBCP対策である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-42','exam-sg','サービスマネジメント・サービスデスク','standard','single_choice','【平成30年度 春期 午前 問42】サービスデスク組織の構造とその特徴のうち，ローカルサービスデスクのものはどれか。','[{"id":"a","text":"サービスデスクを1拠点又は少数の場所に集中し，サービス要員を効率的に配置できる。"},{"id":"b","text":"サービスデスクを利用者の近くに配置し，言語や文化が異なる利用者への対応などができる。"},{"id":"c","text":"サービス要員が複数の地域や部門に分散していても，通信技術によって単一のサービスデスクのようにサービスを提供できる。"},{"id":"d","text":"分散拠点のサービス要員を含め，全員を中央で統括して管理できる。"}]','"b"','ローカルサービスデスクは利用者の近くに配置され，地域・言語・文化などに合わせた対応がしやすい。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-44','exam-sg','ストレージ・RAID','standard','single_choice','【平成30年度 春期 午前 問44】磁気ディスクの耐障害性に関する説明のうち，RAID5に該当するものはどれか。','[{"id":"a","text":"最低でも3台の磁気ディスクが必要で，いずれか1台が故障しても全データを復旧できる。"},{"id":"b","text":"最低でも4台の磁気ディスクが必要で，いずれか2台が故障しても全データを復旧できる。"},{"id":"c","text":"複数台の磁気ディスクに同じデータを書き込むので，いずれか1台が故障しても影響しない。"},{"id":"d","text":"複数台の磁気ディスクにデータを分散して書き込むので，いずれか1台が故障すると全データを復旧できない。"}]','"a"','RAID5は分散パリティを用い，最低3台で構成でき，1台のディスク故障に耐えられる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-45','exam-sg','クラウドサービス・PaaS','standard','single_choice','【平成30年度 春期 午前 問45】PaaS型サービスモデルの特徴はどれか。','[{"id":"a","text":"利用者は，サービスとして提供されるOSやストレージに対する設定や変更をして利用できるが，クラウド基盤自体を変更・拡張することはできない。"},{"id":"b","text":"利用者は，サービスとして提供されるOS，データベースシステム，プログラム言語処理系などを組み合わせて利用できる。"},{"id":"c","text":"利用者は，提供されるアプリケーションを利用できるが，自らアプリケーションを開発することはできない。"},{"id":"d","text":"利用者は，ネットワークを介してサービスとして提供される端末のデスクトップ環境を利用できる。"}]','"b"','PaaSはアプリケーションの開発・実行に必要なOSやミドルウェア，開発環境などをサービスとして提供する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-46','exam-sg','データベース・排他制御','standard','single_choice','【平成30年度 春期 午前 問46】DBMSにおいて，複数のトランザクション処理プログラムが同じデータベースを同時に更新する場合，論理的な矛盾を生じさせないために用いる技法はどれか。','[{"id":"a","text":"再編成"},{"id":"b","text":"整合性制約"},{"id":"c","text":"正規化"},{"id":"d","text":"排他制御"}]','"d"','排他制御によって同時更新の競合を制御し，データの整合性を保つ。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-47','exam-sg','電子メール・SMTPヘッダ','standard','single_choice','【平成30年度 春期 午前 問47】電子メールのヘッダフィールドのうち，SMTPでメッセージが転送される過程で削除されるものはどれか。','[{"id":"a","text":"Bcc"},{"id":"b","text":"Date"},{"id":"c","text":"Received"},{"id":"d","text":"X-Mailer"}]','"a"','Bccの宛先情報は受信者に見えないよう，配送時にヘッダから削除される。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-48','exam-sg','ITアウトソーシング・サービス改善','standard','single_choice','【平成30年度 春期 午前 問48】ITアウトソーシングの活用工程で，発注者が行うことはどれか。','[{"id":"a","text":"移行計画やサービス利用時のコミュニケーション計画を委託先と決定する。"},{"id":"b","text":"移行ツールのテストやサービス利用テストなど，一連のテストを委託先と行う。"},{"id":"c","text":"稼働状況に基づく実績報告や利用者評価を基に，改善案を委託先と取りまとめる。"},{"id":"d","text":"提案依頼書を作成・提示して，委託候補先から提案を受ける。"}]','"c"','活用工程ではサービスの実績や利用者評価を確認し，委託先と継続的な改善を進める。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-49','exam-sg','CSR調達','standard','single_choice','【平成30年度 春期 午前 問49】CSR調達に該当するものはどれか。','[{"id":"a","text":"コストを最小化するために，最も安価な製品を選ぶ。"},{"id":"b","text":"災害時に調達不能となる事態を避けるため，複数の調達先を確保する。"},{"id":"c","text":"自然環境や人権などへの配慮を調達基準として示し，調達先に遵守を求める。"},{"id":"d","text":"物品の購買にEDIを利用し，迅速かつ正確な調達を行う。"}]','"c"','CSR調達では環境，人権，労働慣行などの社会的責任に配慮した調達基準を設ける。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-50','exam-sg','会計・売上総利益','standard','single_choice','【平成30年度 春期 午前 問50】製造原価明細書から損益計算書を作成したとき，売上総利益は何千円か。材料費400千円，労務費300千円，経費200千円，期首仕掛品棚卸高150千円，期末仕掛品棚卸高250千円，期首製品棚卸高120千円，期末製品棚卸高70千円，売上高1,000千円とする。','[{"id":"a","text":"150"},{"id":"b","text":"200"},{"id":"c","text":"310"},{"id":"d","text":"450"}]','"a"','当期総製造費用は900。製品製造原価は900+150−250=800。売上原価は120+800−70=850。売上総利益は1,000−850=150千円。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja');
